class Solution { array<int,26> count(string value){array<int,26> counts{};for(char raw:value){char c=tolower((unsigned char)raw);if(c>='a'&&c<='z')++counts[c-'a'];}return counts;}bool covers(array<int,26>& available,array<int,26>& required){for(int i=0;i<26;++i)if(available[i]<required[i])return false;return true;}public:string shortestCompletingWord(string licensePlate,vector<string>& words){auto required=count(licensePlate);string answer;for(string& word:words){auto available=count(word);if((answer.empty()||word.size()<answer.size())&&covers(available,required))answer=word;}return answer;} };
